create or replace function public.mark_opportunity_viewed(target_match_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.lead_matches%rowtype; begin select * into v from public.lead_matches where id=target_match_id; if v.id is null then raise exception 'Opportunity not found'; end if; if not public.owns_business(v.business_id) then raise exception 'Not authorized for this opportunity'; end if; if v.viewed_at is null then update public.lead_matches set viewed_at=now(),match_status=case when match_status in('pending','sent') then 'viewed' else match_status end,updated_at=now() where id=target_match_id; insert into public.lead_events(lead_id,business_id,actor_id,event_type) values(v.lead_id,v.business_id,(select auth.uid()),'viewed'); end if; end; $$; create or replace function public.express_interest(target_match_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.lead_matches%rowtype; begin select * into v from public.lead_matches where id=target_match_id; if v.id is null then raise exception 'Opportunity not found'; end if; if not public.owns_business(v.business_id) then raise exception 'Not authorized for this opportunity'; end if; if v.interested_at is not null then return; end if; if v.match_status not in('pending','sent','viewed') then raise exception 'This opportunity is no longer available to express interest in'; end if; update public.lead_matches set match_status='interested',interested_at=now(),viewed_at=coalesce(viewed_at,now()),updated_at=now() where id=target_match_id; insert into public.lead_events(lead_id,business_id,actor_id,event_type) values(v.lead_id,v.business_id,(select auth.uid()),'interested'); end; $$; create or replace function public.connect_opportunity(target_match_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.lead_matches%rowtype; begin select * into v from public.lead_matches where id=target_match_id; if v.id is null then raise exception 'Opportunity not found'; end if; if not public.lead_belongs_to_caller(v.lead_id) then raise exception 'Not authorized for this opportunity'; end if; if v.connected_at is not null then return; end if; if v.match_status<>'interested' then raise exception 'A business must be interested before a connection can be made'; end if; update public.lead_matches set match_status='connected',connected_at=now(),updated_at=now() where id=target_match_id; insert into public.lead_events(lead_id,business_id,actor_id,event_type) values(v.lead_id,v.business_id,(select auth.uid()),'connected'); end; $$; create or replace function public.mark_opportunity_won(target_match_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.lead_matches%rowtype; begin select * into v from public.lead_matches where id=target_match_id; if v.id is null then raise exception 'Opportunity not found'; end if; if not public.owns_business(v.business_id) then raise exception 'Not authorized for this opportunity'; end if; if v.match_status in('won','lost') then return; end if; if v.match_status<>'connected' then raise exception 'An opportunity must be connected before an outcome can be recorded'; end if; update public.lead_matches set match_status='won',resolved_at=now(),updated_at=now() where id=target_match_id; insert into public.lead_events(lead_id,business_id,actor_id,event_type) values(v.lead_id,v.business_id,(select auth.uid()),'won'); end; $$; create or replace function public.mark_opportunity_lost(target_match_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.lead_matches%rowtype; begin select * into v from public.lead_matches where id=target_match_id; if v.id is null then raise exception 'Opportunity not found'; end if; if not public.owns_business(v.business_id) then raise exception 'Not authorized for this opportunity'; end if; if v.match_status in('won','lost') then return; end if; if v.match_status<>'connected' then raise exception 'An opportunity must be connected before an outcome can be recorded'; end if; update public.lead_matches set match_status='lost',resolved_at=now(),updated_at=now() where id=target_match_id; insert into public.lead_events(lead_id,business_id,actor_id,event_type) values(v.lead_id,v.business_id,(select auth.uid()),'lost'); end; $$; revoke all on function public.mark_opportunity_viewed(uuid),public.express_interest(uuid),public.connect_opportunity(uuid),public.mark_opportunity_won(uuid),public.mark_opportunity_lost(uuid) from public; grant execute on function public.mark_opportunity_viewed(uuid),public.express_interest(uuid),public.connect_opportunity(uuid),public.mark_opportunity_won(uuid),public.mark_opportunity_lost(uuid) to authenticated;